/* frame_dma_ctrl.h - PS frame-level AXI DMA MM2S controller skeleton */
#ifndef FRAME_DMA_CTRL_H
#define FRAME_DMA_CTRL_H
#include "xil_types.h"
#include "xil_io.h"

#define FRAME_BYTES 0x00119400U
#define FRAME_BASE  0x11000000U
#define FRAME_STORES 3U

/* Tomorrow: replace with xparameters AXI DMA device/base generated by BD. */
typedef struct { u32 dma_base; } frame_dma_ctrl_t;

/* Select an immutable source. Do NOT DMA a currently S2MM-written ring slot. */
static inline u32 frame_dma_safe_slot(u32 s2mm_write_slot) {
  return (s2mm_write_slot + 2U) % FRAME_STORES;
}
static inline u32 frame_dma_slot_addr(u32 slot) { return FRAME_BASE + slot * FRAME_BYTES; }

/* Contract only. Implementation tomorrow uses XAxiDma_SimpleTransfer in MM2S direction. */
int frame_dma_start_mm2s(frame_dma_ctrl_t *ctx, u32 source_phys_addr, u32 byte_count);
int frame_dma_is_done(frame_dma_ctrl_t *ctx);
#endif